//! PowerShell: `Azul.psd1` / `Azul.psm1` (generated by
//! `doc/src/codegen/v2/lang_powershell`), which compiles the C# bindings of
//! `lang_csharp` with `Add-Type`, so the spellings are the C# ones in
//! PowerShell syntax: `[Azul.NativeMethods]::AzCssProperty_textColor(..)`,
//! C-like enums without `Az` (`[Azul.LayoutDisplay]::Flex`), structs and
//! explicit-layout unions as hashtable casts
//! (`[Azul.AzColorU]@{ r = [byte]255; .. }`,
//! `[Azul.AzLayoutWidthValue]@{ Exact = [Azul.AzLayoutWidthValueVariant_Exact]@{ tag = ..; payload = .. } }`).
//! A Vec is marshalled by the `New-CssVec` helper (like `AzulCodegen.Vec` of
//! the C# printer), a String by `New-CssString` (`AzString_fromUtf8`).

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{item_comments, item_doc, module_any, variant_ctor_method, ExprSyntax},
    lower_types::is_c_like_enum,
    CodegenBackend, GeneratedFile,
};

/// The PowerShell printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct PowerShell;

/// The .NET type of an api.json type: C-like enums drop the `Az` prefix.
fn ty_name(ty: &str) -> String {
    if is_c_like_enum(ty) {
        format!("Azul.{ty}")
    } else {
        format!("Azul.Az{ty}")
    }
}

/// A single-quoted PowerShell string (`'` doubled); every other
/// non-printable or non-ASCII character is joined in as `[char]n`.
fn ps_string(s: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut run = String::new();
    for c in s.chars() {
        if (' '..='~').contains(&c) {
            if c == '\'' {
                run.push_str("''");
            } else {
                run.push(c);
            }
        } else {
            if !run.is_empty() || parts.is_empty() {
                parts.push(format!("'{run}'"));
                run.clear();
            }
            parts.push(format!("[char]{}", u32::from(c)));
        }
    }
    if !run.is_empty() || parts.is_empty() {
        parts.push(format!("'{run}'"));
    }
    if parts.len() == 1 {
        parts.remove(0)
    } else {
        format!("({})", parts.join(" + "))
    }
}

/// `[Type]@{ k = v; .. }`.
fn hashtable(ty: String, fields: Vec<Doc>, broken: bool) -> Doc {
    Doc::cat(vec![
        Doc::text(format!("[{ty}]")),
        Doc::list("@{", fields, "; ", "}", true, broken, false),
    ])
}

impl ExprSyntax for PowerShell {
    fn int(&self, value: i128, ty: Prim) -> String {
        match ty {
            Prim::U8 => format!("[byte]{value}"),
            Prim::I8 => format!("[sbyte]{value}"),
            Prim::U16 => format!("[uint16]{value}"),
            Prim::I16 => format!("[int16]{value}"),
            Prim::U32 => format!("[uint32]{value}"),
            Prim::U64 => format!("[uint64]{value}"),
            Prim::I64 => format!("[int64]{value}"),
            Prim::Isize => format!("[IntPtr]{value}"),
            Prim::Usize => format!("[UIntPtr][uint64]{value}"),
            _ => value.to_string(),
        }
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let t = if ty == Prim::F64 { "double" } else { "float" };
        match text {
            "nan" => format!("[{t}]::NaN"),
            "inf" => format!("[{t}]::PositiveInfinity"),
            "-inf" => format!("[{t}]::NegativeInfinity"),
            _ if ty == Prim::F64 => text.to_string(),
            _ => format!("[float]{text}"),
        }
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "$true" } else { "$false" })
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("(New-CssString {})", ps_string(s)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(
            format!("[Azul.NativeMethods]::Az{class}_{}", snake_to_lower_camel(method)),
            args,
            broken,
        )
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("[{}]::{variant}", ty_name(ty))),
            EnumShape::Tagged => Doc::call(
                format!("[Azul.NativeMethods]::Az{ty}_{}", variant_ctor_method(variant)),
                args,
                broken,
            ),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let mut inner = vec![Doc::text(format!("tag = [Azul.Az{ty}_Tag]::{variant}"))];
                if let Some(payload) = args.into_iter().next() {
                    inner.push(Doc::cat(vec![Doc::text("payload = "), payload]));
                }
                hashtable(
                    format!("Azul.Az{ty}"),
                    vec![Doc::cat(vec![
                        Doc::text(format!("{variant} = ")),
                        hashtable(format!("Azul.Az{ty}Variant_{variant}"), inner, broken),
                    ])],
                    broken,
                )
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{k} = ")), v]))
            .collect();
        hashtable(format!("Azul.Az{ty}"), fields, broken)
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("[Azul.NativeMethods]::Az{ty}_create()"));
        }
        Doc::cat(vec![
            Doc::text(format!(
                "(New-CssVec 'Az{ty}_copyFromPtr' ([{}]) ",
                ty_name(elem)
            )),
            Doc::list("@(", items, ", ", ")", false, broken, false),
            Doc::text(")"),
        ])
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("$(throw {})", ps_string(&format!("not expressible: {what}"))))
    }
}

const HELPERS: &str = r"# Copies the items into native memory and lets the C API build the Vec
# (Az<Vec>_copyFromPtr clones them).
function New-CssVec([string]$Copy, [type]$Type, [object[]]$Items) {
    $n = [UIntPtr][uint64]$Items.Count
    if ($Type.IsEnum) {
        [uint32[]]$raw = @($Items | ForEach-Object { [uint32]$_ })
        $handle = [System.Runtime.InteropServices.GCHandle]::Alloc($raw, 'Pinned')
        try { return [Azul.NativeMethods]::$Copy($handle.AddrOfPinnedObject(), $n) }
        finally { $handle.Free() }
    }
    $size = [System.Runtime.InteropServices.Marshal]::SizeOf([type]$Type)
    $buf = [System.Runtime.InteropServices.Marshal]::AllocHGlobal([Math]::Max(1, $size * $Items.Count))
    try {
        for ($i = 0; $i -lt $Items.Count; $i++) {
            [System.Runtime.InteropServices.Marshal]::StructureToPtr($Items[$i], [IntPtr]($buf.ToInt64() + $i * $size), $false)
        }
        return [Azul.NativeMethods]::$Copy($buf, $n)
    }
    finally { [System.Runtime.InteropServices.Marshal]::FreeHGlobal($buf) }
}
";

const NEW_CSS_STRING: &str = r"# An AzString holding the UTF-8 bytes of $S.
function New-CssString([string]$S) {
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($S)
    $buf = [System.Runtime.InteropServices.Marshal]::AllocHGlobal([Math]::Max(1, $bytes.Length))
    try {
        [System.Runtime.InteropServices.Marshal]::Copy($bytes, 0, $buf, $bytes.Length)
        return [Azul.NativeMethods]::AzString_fromUtf8($buf, [UIntPtr][uint64]$bytes.Length)
    }
    finally { [System.Runtime.InteropServices.Marshal]::FreeHGlobal($buf) }
}
";

fn fn_name(item: &Item) -> String {
    format!("Get-{}", item.name.upper_camel())
}

fn item_fn(item: &Item) -> (bool, String) {
    let mut out = String::new();
    for line in &item_comments(&PowerShell, item) {
        out.push_str(&format!("# {line}\n"));
    }
    let name = fn_name(item);
    match item_doc(&PowerShell, item) {
        Ok(doc) => {
            out.push_str(&format!(
                "function {name} {{\n    return {}\n}}\n",
                render(&doc, "    ", 1)
            ));
            (true, out)
        }
        Err(reason) => {
            out.push_str(&format!(
                "# {name}: not expressible with the PowerShell bindings: {reason}\n"
            ));
            (false, out)
        }
    }
}

impl CodegenBackend for PowerShell {
    fn lang(&self) -> &'static str {
        "powershell"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["pwsh", "ps1"]
    }

    fn display_name(&self) -> &'static str {
        "PowerShell"
    }

    fn extension(&self) -> &'static str {
        "ps1"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "# Generated by azul-css codegen (PowerShell). Do not edit by hand.\n# Dot-source \
             after Import-Module Azul.psd1: . ./styles.ps1\n",
        );
        if module_any(m, &|e| matches!(e, Expr::Vec { .. })) {
            out.push('\n');
            out.push_str(HELPERS);
        }
        if module_any(m, &|e| matches!(e, Expr::Str(_))) {
            out.push('\n');
            out.push_str(NEW_CSS_STRING);
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item).1);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "# Copy target/codegen/Azul.psd1 + Azul.psm1 and libazul here, then: pwsh \
             ./main.ps1\nImport-Module ./Azul.psd1\n. ./styles.ps1\n\n",
        );
        for item in m.items.iter().filter(|i| item_fn(i).0) {
            let name = fn_name(item);
            let var = item.name.lower_camel();
            main.push_str(&format!(
                "${var} = {name}\nWrite-Host \"{name}: $(${var}.len) properties\"\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "styles.ps1".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.ps1".to_string(),
                contents: main,
            },
        ]
    }
}
